INSERT OR IGNORE INTO products (slug,title,description,category,status,images,options,variants,seo_title,seo_description,og_image,sort_all,sort_cat) VALUES ('5-tier-3-tier-shelf-connector','5-Tier & 3-Tier Shelf Connector','<p>🔗 5-Tier &amp; 3-Tier Shelf Connector is a modular accessory designed to connect and extend compatible 5-tier and 3-tier display shelves.</p>
