INSERT OR IGNORE INTO products (slug,title,description,category,status,images,options,variants,seo_title,seo_description,og_image,sort_all,sort_cat) VALUES ('heart-tealight-candle-holder','Heart Tealight Candle Holder','<p>Add a warm, romantic glow to your home with this elegant Heart Tealight Candle Holder. Featuring intricate laser-cut scrollwork and layered heart-shaped panels, this hanging lantern creates beautiful light patterns while showcasing the flickering flame through its center heart window.</p>
<p>Crafted from premium birch wood, this decorative tealight holder is perfect for cozy evenings, weddings, anniversaries, Valentine''s Day, or everyday home décor. Hang it by a window, wall, porch, or use it as a charming centerpiece for special occasions.</p>
<p>Its timeless heart design complements farmhouse, rustic, Scandinavian, cottagecore, and romantic interiors.</p>
<p>MATERIALS<br>Premium Birch Wood<br>Precision Laser-Cut Components<br>Natural Wood Finish<br>Jute Hanging Rope</p>
<p>Tealight candle not included.</p>
<p>SIZE<br>Dimensions:<br>Width: 5.91 inches (15 cm)<br>Depth: 1.85 inches (4.7 cm)<br>Height: 5.51 inches (14 cm)</p>
<p>HIGHLIGHTS<br>❤️ Elegant layered heart silhouette with decorative scrollwork<br>🕯️ Designed for standard LED or battery-operated tealight candles<br>✨ Creates beautiful ambient lighting through the heart-shaped opening<br>🌿 Lightweight construction with natural wood finish<br>🏡 Perfect for farmhouse, rustic, cottage, Scandinavian, and romantic home décor<br>🎁 Wonderful gift for weddings, anniversaries, Valentine''s Day, Mother''s Day, birthdays, and housewarming celebrations</p>
<p>HOW TO USE<br>Simply place a battery-operated LED tealight inside and hang the ornament using the included rope.</p>
<p>Perfect for:<br>Wall decoration<br>Window décor<br>Bedroom ambiance<br>Wedding decoration<br>Romantic dinner centerpiece<br>Holiday decoration</p>
<p>Safety Note: For safety, we recommend using LED flameless tealight candles rather than open-flame candles.</p>
<p>SHIPPING &amp; PROCESSING<br>Processing Time: 3–5 business days<br>Ships From: Vietnam<br>Estimated Delivery: 8–12 business days worldwide<br>Tracking information will be provided after shipment.</p>
<p>#HeartDecor #TealightHolder #WoodenLantern #LaserCutDecor #RomanticDecor #ValentinesGift #WeddingDecor #FarmhouseDecor #WallHanging #RusticHome #WoodCraft #CozyHome #HandmadeGift</p>','wooden-kits','published','["https://cdn.shopify.com/s/files/1/0962/4138/5545/files/2_23621c95-41f0-42b0-ba73-c5bcf221ab47.png?v=1784622794", "https://cdn.shopify.com/s/files/1/0962/4138/5545/files/1_45d36d89-1762-4d91-8006-ba9e17936dbe.png?v=1784622793", "https://cdn.shopify.com/s/files/1/0962/4138/5545/files/3_4002b2ff-f01a-43c0-b407-84488c226561.png?v=1784622794", "https://cdn.shopify.com/s/files/1/0962/4138/5545/files/4_1803c218-c2ba-4051-9402-578264f5c3a3.png?v=1784622793", "https://cdn.shopify.com/s/files/1/0962/4138/5545/files/5_14810143-c111-4519-be54-7c3c8877c345.png?v=1784622794", "https://cdn.shopify.com/s/files/1/0962/4138/5545/files/6_36958e02-1565-4d2d-bf2f-eb87128cf736.png?v=1784622794", "https://cdn.shopify.com/s/files/1/0962/4138/5545/files/7_c30ef75e-830f-43d5-adfb-4a5e12f98973.png?v=1784622794", "https://cdn.shopify.com/s/files/1/0962/4138/5545/files/8_98278f62-71d6-4169-8d87-67c25f06c3a3.png?v=1784622793", "https://cdn.shopify.com/s/files/1/0962/4138/5545/files/9_4e70eb26-80c3-4c32-9017-3be355831f03.png?v=1784622794", "https://cdn.shopify.com/s/files/1/0962/4138/5545/files/10_23cd9af3-9894-494a-998f-a3732b95722a.png?v=1784622794", "https://cdn.shopify.com/s/files/1/0962/4138/5545/files/11_9db43d86-56b6-4d85-bbe4-85e3aad8b0e1.png?v=1784622794", "https://cdn.shopify.com/s/files/1/0962/4138/5545/files/12_bb83954d-895b-4409-87de-a0c69ffc6eae.png?v=1784622794"]','[]','[{"key":"heart-tealight-candle-holder::Default Title","label":"Default Title","option1":"Default Title","option2":null,"option3":null,"price":29.9,"compareAt":44.85,"sku":"HT02","image":null}]',NULL,NULL,NULL,19,8);
