INSERT OR IGNORE INTO products (slug,title,description,category,status,images,options,variants,seo_title,seo_description,og_image,sort_all,sort_cat) VALUES ('smiski-vhs-display-shelf-1-12-scale-blockbuster-miniature-shelf-smiski-display-stand-custom-genre-shelf-dollhouse-accessory','Smiski VHS Display Shelf 1:12 Scale','<p>Step into a tiny retro movie world 🎬💙<br>This mini VHS display shelf is inspired by classic video rental stores, bringing cozy nostalgic vibes right to your desk ✨</p>
<p>Perfect for displaying your favorite tiny figures like Smiski 👀💚 or other collectibles, this shelf adds a unique and playful aesthetic to your space!</p>
<p>🎨 Customize your vibe:<br>You can choose your own genre label to match your collection!<br>Examples: Horror | Romance | Anime | Fantasy | Action |....</p>
<p>📦 What you get:<br>• 1 Mini display shelf</p>
<p>🚫 NOT included:<br>• VHS cases<br>• VHS tapes<br>• Figures</p>
